export type StaffProjectionCase = "saved" | "unknown_fee" | "unknown_payoff_policy" | "unknown_currency" | "on_demand";
export function staffProjection(kind: StaffProjectionCase, request: InvestorProjectionRequest, working = false, fingerprint = "a".repeat(64)): InvestorReturnProjection {
  const key = request.investment_amount === 25000 ? `exit${request.exit_month}_stake25000` : kind === "unknown_fee" || kind === "unknown_payoff_policy" || kind === "unknown_currency" ? kind : "exit6";
  if (!serviceCases[key]) throw new Error(`Unsupported synthetic canonical projection ${key}`);
  const raw = structuredClone(serviceCases[key]) as Omit<InvestorReturnProjection, "source">;
  const value: InvestorReturnProjection = { ...raw, source: { kind: working ? "staff_preview" : "staff_saved", id: shellListing().profile_id!, budget_revision: 1, terms_version: 4, updated_at: "2026-11-12T18:00:00Z", fingerprint } };
  value.request = { ...request };
  value.selected_exit = value.payoff_curve.find(point => point.month === request.exit_month) ?? (value.full_term?.month === request.exit_month ? value.full_term : value.selected_exit);
  if (kind === "on_demand") { value.payoff_curve_status = "on_demand"; value.payoff_curve = []; }
  return value;
}
